"""Diagnose outputs generated by base model for coding and JSON prompts."""

from pathlib import Path
import sys

REPO_ROOT = Path(__file__).resolve().parent.parent
if str(REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(REPO_ROOT))

from scripts.evaluate_sft_4k import SFT4KEvaluator


def main():
    evaluator = SFT4KEvaluator(REPO_ROOT / "checkpoints/modern_gpts_100m_4k_pilot/checkpoint_step_2000.pt")

    coding_prompt = "Write a Python function `is_even(n)` that returns True if n is even, else False."
    msgs = [
        {"role": "system", "content": "You are an expert Python coding assistant. Output only Python code."},
        {"role": "user", "content": coding_prompt},
    ]
    resp = evaluator.generate_response(msgs, max_new_tokens=64, temperature=0.0)
    print("Coding response:\n", repr(resp))

    json_prompt = 'Output a JSON object with keys "status" set to "success" and "code" set to 200.'
    msgs_json = [
        {"role": "system", "content": "You are a structured data extractor. Output strictly valid JSON."},
        {"role": "user", "content": json_prompt},
    ]
    resp_json = evaluator.generate_response(msgs_json, max_new_tokens=64, temperature=0.0)
    print("JSON response:\n", repr(resp_json))


if __name__ == "__main__":
    main()

